export const supplements = {
 'math-1':{title:'乘除符號與分配律',points:['乘除先數負因子的個數：偶數個負因子得正，奇數個得負；只要有一個因子是 0，乘積就是 0。','分配律 a×c+b×c=(a+b)×c。減去負數先改成加法，再提共同因數，避免把符號留錯。'],rows:[['符號','(−2)×(−3)×(−4)=−24','三個負因子，結果為負'],['共同因數','2.4×98−(−0.6)×98=(2.4+0.6)×98=294','先處理減去負數'],['估算檢核','3×98 接近 300 且稍小','估算只能檢核，不能取代精確計算']],task:'不直式計算，求 7.8×101−(−2.2)×101，並說明符號。',answer:'(7.8+2.2)×101=1010。'},
 'math-2':{title:'最大真因數反推與質因數指數條件',points:['正整數 N 的最大真因數（扣掉自己以外的最大正因數）必等於 N 除以它的最小質因數 p，即 最大真因數＝N/p。','若 A 是 B 的倍數，則 A 的標準分解式中每一個質因數次方皆大於或等於 B 的對應次方。'],rows:[['最大真因數','偶數 N 的最小質因數為 2','最大真因數為 N/2'],['奇數反推','若最大真因數為 35＝5×7','最小質因數不可大於 5，故原數 N＝3×35＝105 或 5×35＝175（依題意最小質因數判定）'],['指數檢核','比較各質因數次方上下界','代回分解式確認沒有更小的質因數']],task:'某正整數 N 不是偶數，且除自己外最大的因數為 45，若 N 的最小質因數為 3，求 N。',answer:'最大真因數＝N÷最小質因數＝45，所以 N＝45×3＝135（驗證：135＝3³×5，最小質因數確為 3）。'},
 'math-3':{title:'指數律、數量級與面積圖示跨表徵比較',points:['aᵐ×aⁿ=aᵐ⁺ⁿ；aᵐ÷aⁿ=aᵐ⁻ⁿ（a≠0）；(aᵐ)ⁿ=aᵐⁿ。a⁰=1、a⁻ⁿ=1/aⁿ，兩者都要求 a≠0。','(ab)ⁿ=aⁿbⁿ，但 (a+b)ⁿ 不能拆成 aⁿ+bⁿ。比較正的科學記號，先比較十的次方，指數相同再比較係數；將圖表區塊大小排序轉為科學記號時，先排指數高低再比對係數區間。'],rows:[['同底相乘','2³×2⁴=2⁷','指數相加'],['同次方','2³×5³=(2×5)³=1000','底數相乘'],['負指數','10⁻³=0.001','不是負數'],['量級與圖示比較','4.2×10⁵＜8.5×10⁵＜1.3×10⁶','先排 10ⁿ 次方，再對照圖示面積大小順序']],task:'判斷 3²×3⁴ 與 (3²)⁴ 是否相等，寫出理由。',answer:'前者為 3⁶，後者為 3⁸，不相等。'},
 'math-4':{title:'含負分數移項與滿額折扣對話建模',points:['去分母時等號兩邊每一項（含常數項）都要同乘分母的最小公倍數；分子為多項式且前面是減號時，務必先加括號再變號。','滿額折扣建模先確認「折扣門檻（如滿千折百或打折）」作用在總價還是單品，再按比例分攤回各人應付金額。'],rows:[['去分母防呆','x − (2x−3)/4 ＝ 1 → 4x − (2x−3) ＝ 4','括號內 −3 變號為 +3'],['折扣後分攤','原價比 3：2，同享八折後應付比仍為 3：2','固定折數不改變分攤比例'],['定額折價分攤','總價折抵 100 元時，需確認依原價比例或人數平分','先列原價總和再扣減折價']],task:'解方程式 x − (x−2)/3 ＝ 2，並驗算。',answer:'同乘 3 得 3x − (x−2) ＝ 6 → 2x＋2＝6 → x＝2；代回 2 − 0 ＝ 2 成立。'},
 'math-6':{title:'比例分攤、加權總量與測量誤差方向比較',points:['已知甲：乙＝a：b，可設甲＝ak、乙＝bk（k≠0）；共同打折或同乘常數時比例不變，但加減固定金額後比例會改變。','在乘積關係（如總量＝單位量×數量）中，若實際單位量比標示值大，則達到相同總量所需的數量會比預期少（反比方向判斷）。'],rows:[['設參數建模','甲：乙＝3：5，總和 240 → 3k＋5k＝240','得 k＝30，甲＝90、乙＝150'],['折扣分攤','原價比 a：b，打折後實付比仍為 a：b','由實付差額可反推原價差額'],['誤差方向判讀','總距離固定，若步長變大則步數變少','先固定控制變因，再看正反比方向']],task:'甲、乙兩件商品原價比為 4：3，同時打八折後甲比乙貴 120 元，求兩商品原價。',answer:'設原價 4k、3k，0.8×(4k−3k)＝120 → 0.8k＝120 → k＝150，原價分別為 600 元與 450 元。'},
 'math-8':{title:'平面坐標距離與雙向列聯表（聯集／否定條件）排除',points:['水平線段 y 坐標固定，距離＝|x₂−x₁|；鉛直線段 x 坐標固定，距離＝|y₂−y₁|。','雙向分類表（如等級×尺寸）判讀時，「不符合（A 或 B）」等於「既不是 A 也不是 B」，在表格中直接圈出留存格位相加，避免重複扣減聯集交集。'],rows:[['水平／鉛直距離','(−3, 4) 到 (5, 4) 距離為 8','同 y 坐標取 x 差之絕對值'],['雙向表小計','各列總和＝總數，各欄總和＝總數','利用邊際總和反推未知格'],['否定聯集排除','淘汰「良級或大果」＝只保留「非良級且非大果」','直接鎖定目標列與目標欄的交集格']],task:'果園分優、良、普三級與大、中、小三種尺寸（3×3 表），若挑出「良級或大果」後，剩下的水果位於表格哪些位置？',answer:'位於「優級或普級」且屬於「中果或小果」的 4 個交叉格位。'},
 'math-9':{title:'多項式長除法與驗算',points:['按次方由高到低排列，缺項補 0。用被除式目前最高次項除以除式最高次項，得到下一個商項；乘回、相減後繼續。','被除式=除式×商式+餘式；餘式次數必須小於除式次數。除以一次式時，餘式為常數或 0。'],rows:[['第一輪','(2x²+3x−4)÷(x+2)：先取 2x','减去 2x²+4x 得 −x−4'],['第二輪','取 −1；减去 −x−2','餘式 −2'],['驗算','(x+2)(2x−1)−2=2x²+3x−4','商 2x−1，餘 −2']],task:'求 (3x²+2x−5)÷(x+1) 的商式、餘式，並乘回驗算。',answer:'商式 3x−1，餘式 −4；(x+1)(3x−1)−4=3x²+2x−5。'},
 'math-10':{title:'最簡根式與根式四則',points:['把根號內的數分成完全平方因數與剩餘因數。對非負數 a、b，√(ab)=√a√b；不能把 √(a+b) 拆成 √a+√b。','只有根號內相同的最簡根式才能直接合併係數。分母有根號時，可同乘適當根式使分母有理化。'],rows:[['化簡','√72=√(36×2)=6√2','先提完全平方因數'],['合併','√50−√8=5√2−2√2=3√2','化簡後再合併'],['相乘','√3×√12=√36=6','根號內相乘'],['有理化','1/√2=√2/2','分子分母同乘 √2']],task:'將 √180 化為 a√b 的最簡根式，求 a+b。',answer:'√180=6√5，所以 a+b=11。'},
 'math-13':{title:'等比數列與逐年成長',points:['等比數列的相鄰兩項具有固定倍率 r，第 n 項 aₙ=a₁rⁿ⁻¹。固定增加一個數是等差，固定增加一定百分比是等比。','從基準年到目標年，乘倍率的次數等於經過的年數；增加 p% 的倍率是 1+p/100，不是 p/100。'],rows:[['等差','100、110、120','每次加 10'],['等比','100、110、121','每次乘 1.1'],['時間間隔','2024 到 2027 有 3 次成長','不是 4 次'],['模型','初值 800，每年增加 3%，四年後 800×1.03⁴','假設每年成長率固定']],task:'初值 500，每年減少 2%，三年後的數量如何表示？',answer:'500×0.98³；每年留下前一年的 98%。'},
 'math-14':{title:'全等判定、外角定理與等腰角平分輔助線',points:['三角形外角等於兩不相鄰內角和；同一三角形中大邊對大角、等邊對等角。','直角三角形斜邊中點與等腰三角形角平分線結合時，先連斜邊中線拆出兩個等腰三角形，再利用外角定理傳遞角度關係。'],rows:[['外角傳遞','∠ACD＝∠A＋∠B','不需先求第三內角再減 180°'],['等腰三線合一','頂角平分線垂直平分底邊','構成對稱的兩個直角三角形'],['邊角不等','同一三角形中 AB＞AC ⇔ ∠C＞∠B','跨三角形時需藉助共用邊或外角橋接']],task:'在 △ABC 中，AB＝AC，∠A＝40°，D 為 BC 上一點使得 AD 平分 ∠BAC，求 ∠ADB 與 ∠B。',answer:'∠B＝(180°−40°)÷2＝70°；頂角平分線垂直底邊，故 ∠ADB＝90°。'},
 'math-15':{title:'平行線等距軌跡、中線交點與角平分線尺規判讀',points:['與一直線距離相等的點軌跡為平行線；兩組平行線若間距相等，其交錯構成的平行四邊形必為四邊等長的菱形，對角線即為內角平分線。','若兩組平行線的間距不相等，則其構成一般平行四邊形，對角線不會平分內角；尺規作角平分線是以頂點為圓心取等長兩邊構成菱形對稱。'],rows:[['角平分線軌跡','到角兩邊距離相等','尺規作圖以等半徑鎖定對稱交點'],['平行線間距比對','兩平行線帶等寬時交出菱形','菱形對角線平分頂角'],['反例檢驗','長方形對角線不平分 90° 角（除非正方形）','不等寬平行線中線交點不在角平分線上']],task:'說明為何長寬不等的長方形（如長 8、寬 4），其對角線不會是直角的角平分線。',answer:'若平分 90° 則為 45°-45°-90° 等腰直角三角形，長寬必須相等，故長寬不等時對角線不平分內角。'},
 'math-16':{title:'複合圖形相似三角形辨識與比例分段',points:['在複合幾何圖形中，若出現等角（如平行內錯角、共用角或互餘角），先依對應頂點順序寫出 △ABC～△DEF，再列對應邊比例。','平行截線求底邊比時，必須用「小三角形側邊：大三角形完整側邊」，不可誤用下段截線長；計算面積時先區分「相似平方比」與「共高底邊一次比」。'],rows:[['AA 相似定位','共用角＋一組等角 → 兩三角形相似','先把對應頂點對齊再列比例式'],['完整側邊比','AD：DB＝2：3 ⇒ DE：BC＝2：(2+3)＝2：5','底邊比等於小比大完整邊'],['面積雙模型','相似面積比＝k²；同高面積比＝底邊比 k','複合圖形常分兩步轉換']],task:'△ABC 中 D、E 分別在 AB、AC 上且 DE∥BC，若 AD＝4、DB＝6，求 △ADE 與四邊形 DBCE 的面積比。',answer:'AD：AB＝4：10＝2：5，面積比 △ADE：△ABC＝4：25，故 △ADE：四邊形 DBCE＝4：(25−4)＝4：21。'},
 'math-17':{title:'圓內接長方形直徑性質、弦心距與累積弧度定位',points:['圓周角為 90° 時所對的弦必為直徑；因此圓內接長方形的兩條對角線必為圓的直徑且交於圓心。','圓心到弦的垂線（弦心距 d）平分弦長 L，滿足 r²＝d²＋(L/2)²；在圓周上依序標點時，利用累積弧度除以全圓 360°（或等分數）可精準判斷兩點是否對稱於直徑兩端。'],rows:[['直徑判準','∠ABC＝90°（頂點在圓上）⇔ AC 為直徑','長方形對角線交點即為外接圓圓心'],['弦心距畢氏定理','半徑 r、弦心距 d、半弦 L/2','r²＝d²＋(L/2)²'],['累積弧長定位','對徑點相差半圓（180° 或半周長）','先算各點累積弧長再找差值為半圓之點對']],task:'圓 O 半徑為 10，圓內一弦 AB 長 16，求圓心 O 到弦 AB 的距離（弦心距）。',answer:'弦心距垂直平分弦，半弦長為 8，由畢氏定理得 d＝√(10²−8²)＝6。'},
 'math-19':{title:'等可能樣本空間與兩步抽取',points:['機率=符合條件的等可能結果數÷所有等可能結果數。必須先確認每一個基本結果等可能，不能直接把不同總和當作等可能。','兩袋各獨立抽一球，可用二維表列出所有有序結果。若是不放回抽取，第二步的可能結果會改變，不能照用獨立抽取的表格。'],rows:[['列舉','甲袋 1、2；乙袋 2、3','(1,2)、(1,3)、(2,2)、(2,3)'],['求和','總和為 3、4、4、5','4 出現兩次'],['機率','P(總和=4)=2/4=1/2','不同總和的機率不相同']],task:'甲袋 1、2、3，乙袋 1、2，各獨立等可能抽一球，總和 3 的機率是多少？',answer:'六個等可能結果中，(1,2)、(2,1) 合格，所以是 2/6=1/3。'},
 'math-20':{title:'直角三角形外心（斜邊中點）與角平分線輔助推理',points:['直角三角形的外心必在「斜邊中點」，因此斜邊中點到三頂點等距離（OA＝OB＝OC＝斜邊/2），將直角三角形自然分割為兩個等腰三角形。','當直角三角形同時出現斜邊中點與內角平分線時，利用等腰三角形底角相等與外角定理，可逐步推導出各線段夾角與等腰關係。'],rows:[['直角外心位置','斜邊中點 M 到三頂點等距','MA＝MB＝MC＝AB/2'],['內心面積公式','△面積＝(1/2)×r×周長','直角三角形 r＝(a＋b−c)/2'],['重心比例','中線交點分中線為 2：1','重心到直角頂點距離＝斜邊/3']],task:'直角 △ABC 中 ∠C＝90°，M 為斜邊 AB 中點，若 ∠A＝32°，求 ∠BMC 的度數。',answer:'M 為外心，故 MA＝MC，△MAC 為等腰三角形，∠MCA＝∠A＝32°；由外角定理得 ∠BMC＝∠A＋∠MCA＝64°。'},
 'math-23':{title:'正多邊形中心距（30-60-90 三角形）與旋轉對稱建模',points:['正六邊形可由中心分割為 6 個全等的正三角形；設邊長為 a，則中心到頂點距離為 a，中心到邊的垂直距離（內切圓半徑／邊心距）為 (√3/2)a。','正多邊形具旋轉對稱性（正 n 邊形每旋轉 360°/n 重合）；計算鑲嵌或包裝容器最小邊長時，須比較「頂點對頂點（2a）」與「平行對邊距離（√3a）」兩個方向的極值。'],rows:[['正六邊形拆解','中心連六頂點得 6 個正三角形','外接圓半徑 R＝a'],['30-60-90 邊心距','中心作邊的垂線平分 60° 角','邊長比 1：√3：2，邊心距 r＝(√3/2)a，對邊距＝√3a'],['旋轉極值檢核','轉動時最大跨距為對角線 2a，最小跨距為對邊距 √3a','依容器限制方向代入根號近似值比較']],task:'邊長為 6 公分的正六邊形，其兩條平行對邊之間的垂直距離為多少公分？',answer:'正六邊形中心到邊距離為 3√3 公分，兩平行對邊距離為 2×3√3＝6√3 公分。'},
 'math-24':{title:'圓與菱形重疊弦心距、圓內接矩形與扇形弧長',points:['當菱形頂點落在圓上或圓心與菱形頂點共構時，優先利用「菱形四邊等長＝圓半徑 r」及「菱形對角線互相垂直平分」，將重疊線段拆解為直角三角形求弦心距與對角線長。','扇形弧長＝2πr×(θ/360)，圓上兩點最短劣弧角度決定其對應圓心角與弦長大小。'],rows:[['圓與菱形共構','若菱形邊長等於半徑 r，常構成正三角形（60°/120°）','對角線長分別為 r 與 √3r'],['對角線垂直平分','菱形對角線交點構成四個全等直角三角形','配合畢氏定理求未知半弦長'],['弧度與直徑','圓內接矩形對角線必過圓心','相差 180° 弧度的兩頂點連線即為直徑']],task:'圓 O 半徑為 8，圓上三點 A、B、C 與圓心 O 恰好構成菱形 OABC，求對角線 AC 的長度。',answer:'菱形四邊等長且 OA＝OB＝OC＝AB＝BC＝8，故 △OAB 與 △OBC 皆為邊長 8 的正三角形，AC＝2×(8×√3/2)＝8√3。'},
 'math-26':{title:'直角柱的底面與側稜',points:['直角柱的側稜垂直於底面。底面內相交的兩條邊所夾的角，由底面多邊形決定；底面邊與通過同一頂點的側稜所夾的角是直角。','立體透視圖會使角度看起來失真，必須用直角柱、正三角形等文字條件判斷，不可直接量圖上的角。'],rows:[['正三角形底面','每個內角為 60°','由正三角形性質判斷'],['直角柱側稜','側稜與底面垂直','與通過垂足的底面邊夾 90°'],['斜角柱','不能假設側稜垂直底面','先查題目條件']],task:'底面是正方形的直角柱，底面相鄰兩邊、底面邊與相接側稜的夾角各為多少？',answer:'兩者都是 90°；理由分別是正方形內角與側稜垂直面。'}
};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function supplementFor(u) {
  if (!u) return null;
  if (supplements[u.id]) return supplements[u.id];
  const wc = workedCases[u.id];
  const q = u.questions?.[1] || u.questions?.[0];
  return {
    title: `${u.title} · 進階條件辨析與實戰檢核`,
    points: [
      wc ? wc.teaching : u.concept,
      `【適用邊界與易錯防線】${u.pitfall} ${wc ? wc.check : ''}`
    ],
    rows: [
      ['審題焦點', wc ? wc.problem : u.title, wc && wc.steps[0] ? wc.steps[0] : u.example],
      ['核心推演', wc && wc.steps[1] ? wc.steps[1] : u.concept, wc && wc.steps[2] ? wc.steps[2] : '逐步核對已知條件與未知目標'],
      ['邊界檢核', wc ? wc.check : u.pitfall, `完成遷移：${u.task}`]
    ],
    task: q ? `${q.prompt}（試著不看選項先說出判斷根據）` : u.task,
    answer: q ? `正確結論為「${q.options[q.answer]}」。解析：${q.explanation}` : u.example
  };
}
export function renderSupplement(u){const s=supplementFor(u);return s?`<section class="teaching-notes"><h3>${esc(s.title)}</h3>${s.points.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="table-wrap"><table class="teaching-table"><caption>${esc(s.title)} · 條件、做法與檢核</caption><thead><tr><th>辨識</th><th>做法</th><th>檢核</th></tr></thead><tbody>${s.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><strong>自己試一次：</strong>${esc(s.task)}</p><details><summary>查看理由</summary><p>${esc(s.answer)}</p></details></section>`:'';}
